vertex:
#version 300 es

struct VS_OUT
{
    vec2 vTexCoords;
    vec3 vNormal;
    vec3 vPosition;
    vec3 vPositionWs;
    vec3 vPositionVs;
};

layout(std140) uniform ObjectUniformBuffer
{
    mat4 g_mModel;
    mat4 g_mView;
    mat4 g_mProj;
    vec3 g_vLightPos;
    vec3 g_vLightColor;
    vec3 g_vCameraPos;
} g_oUbo;

out vec2 vdspv_fsin0_vTexCoords;
out vec3 vdspv_fsin0_vNormal;
out vec3 vdspv_fsin0_vPosition;
out vec3 vdspv_fsin0_vPositionWs;
out vec3 vdspv_fsin0_vPositionVs;
layout(location = 2) in vec2 texCoords;
layout(location = 1) in vec3 normal;
layout(location = 0) in vec3 position;

void main()
{
    vdspv_fsin0_vTexCoords = texCoords;
    vdspv_fsin0_vNormal = normal;
    vdspv_fsin0_vPosition = vec3((g_oUbo.g_mModel * vec4(position, 1.0)).xyz);
    vec4 pos = g_oUbo.g_mModel * vec4(position, 1.0);
    vdspv_fsin0_vPositionVs = vec3((g_oUbo.g_mView * pos).xyz);
    vdspv_fsin0_vPositionWs = pos.xyz;
    gl_Position = (g_oUbo.g_mProj * g_oUbo.g_mView) * pos;
    gl_Position.z = 2.0 * gl_Position.z - gl_Position.w;
    gl_Position.y = -gl_Position.y;
}

fragment:
#version 300 es
precision mediump float;
precision highp int;

struct VS_OUT
{
    highp vec2 vTexCoords;
    highp vec3 vNormal;
    highp vec3 vPosition;
    highp vec3 vPositionWs;
    highp vec3 vPositionVs;
};

layout(std140) uniform ObjectUniformBuffer
{
    highp mat4 g_mModel;
    highp mat4 g_mView;
    highp mat4 g_mProj;
    highp vec3 g_vLightPos;
    highp vec3 g_vLightColor;
    highp vec3 g_vCameraPos;
} g_oUbo;

uniform highp sampler2D Color;

in highp vec2 vdspv_fsin0_vTexCoords;
in highp vec3 vdspv_fsin0_vNormal;
in highp vec3 vdspv_fsin0_vPosition;
in highp vec3 vdspv_fsin0_vPositionWs;
in highp vec3 vdspv_fsin0_vPositionVs;
layout(location = 0) out highp vec4 fragColor;

highp vec3 lambert(highp vec3 vLightDir, highp vec3 vNormal)
{
    return g_oUbo.g_vLightColor * dot(normalize(vLightDir), normalize(vNormal));
}

highp vec3 ambient(highp vec3 vLightColor)
{
    return vLightColor * 0.20000000298023223876953125;
}

highp vec3 specular(highp vec3 vLightDir, highp vec3 vNormal, highp vec3 vCameraDir, highp float fShininess)
{
    highp vec3 vReflection = reflect(normalize(-vLightDir), normalize(vNormal));
    return g_oUbo.g_vLightColor * pow(max(dot(normalize(vCameraDir), vReflection), 0.0), fShininess);
}

void main()
{
    highp vec3 vLightDir = normalize(g_oUbo.g_vLightPos - vdspv_fsin0_vPosition);
    highp vec3 param = vLightDir;
    highp vec3 param_1 = vdspv_fsin0_vNormal;
    highp vec3 vLambert = lambert(param, param_1);
    highp vec3 param_2 = g_oUbo.g_vLightColor;
    highp vec3 vAmbient = ambient(param_2);
    highp vec3 vCameraDir = normalize(g_oUbo.g_vCameraPos - vdspv_fsin0_vPosition);
    highp vec3 param_3 = vLightDir;
    highp vec3 param_4 = vdspv_fsin0_vNormal;
    highp vec3 param_5 = vCameraDir;
    highp float param_6 = 32.0;
    highp vec3 vSpecular = specular(param_3, param_4, param_5, param_6);
    highp vec4 vColor = texture(Color, vdspv_fsin0_vTexCoords) * 0.75;
    vColor.z *= 1.25;
    highp vec3 fogColor = vec3(0.2800000011920928955078125, 0.87999999523162841796875, 1.0);
    highp float fogStart = 80.0;
    highp float fogEnd = 200.0;
    highp float fogAmount = clamp((length(vdspv_fsin0_vPositionVs) - fogStart) / (fogEnd - fogStart), 0.0, 1.0);
    fragColor = vec4(vLambert + vAmbient, 1.0) * vColor;
    fragColor = mix(fragColor, vec4(fogColor, 1.0), vec4(fogAmount));
    if (fragColor.w < 0.100000001490116119384765625)
    {
        discard;
    }
}
